package io.agentshield;

import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;

public final class DesktopApp extends JFrame {
    private final JTextField pid=new JTextField(8);
    private final JTextField policyPath=new JTextField(30);
    private final JTextField auditPath=new JTextField(24);
    private final JTextField auditKeyPath=new JTextField(24);
    private final JCheckBox strictPrivacy=new JCheckBox("Strict privacy");
    private final JLabel score=new JLabel("Not monitoring");
    private final JLabel identity=new JLabel("No process selected");
    private static DefaultTableModel model(String... columns){return new DefaultTableModel(columns,0){public boolean isCellEditable(int row,int column){return false;}};}
    private final DefaultTableModel credentials=model("Severity","Credential-like exposure","Source");
    private final DefaultTableModel resources=model("Severity","Resource type","Observed identifier","Protocol","Local endpoint","Remote endpoint","State");
    private final DefaultTableModel findings=model("Severity","Rule","Finding","Evidence","Recommended action");
    private final DefaultTableModel activity=model("Time","Change","Severity","Area","Observed access","Status");
    private final DefaultTableModel policy=model("Decision","Area","Observed access","Reason","Status");
    private final JButton start=new JButton("Start monitoring");
    private final JButton stop=new JButton("Stop");
    private final JButton verifyAudit=new JButton("Verify audit log");
    private final String executable;
    private volatile Process monitor;
    private volatile Process auditVerifier;
    private volatile Thread monitorWorker;
    private volatile boolean stopRequested;

    static List<String> buildMonitorCommand(String executable,String target,String policy,boolean strict){return buildMonitorCommand(executable,target,policy,strict,"","");}
    static List<String> buildMonitorCommand(String executable,String target,String policy,boolean strict,String audit,String auditKey){var command=new ArrayList<>(List.of(executable,"watch",target,"--interval","1000","--format","tsv"));if(!policy.isBlank()){command.add("--policy");command.add(policy);}if(strict){command.add("--privacy");command.add("strict");}if(!audit.isBlank()){command.add("--audit");command.add(audit);command.add("--audit-key");command.add(auditKey);}return List.copyOf(command);}
    static Object[] policyRow(String[] fields){return fields.length>5&&fields[0].equals("POLICY")?new Object[]{fields[1],fields[2],fields[3],fields[4],fields[5]}:null;}
    static Object[] resourceRow(String[] fields){return fields.length>3&&fields[0].equals("RESOURCE")?new Object[]{fields[1],fields[2],fields[3],fields.length>4?fields[4]:"",fields.length>5?fields[5]:"",fields.length>6?fields[6]:"",fields.length>7?fields[7]:""}:null;}
    static List<String> buildAuditVerifyCommand(String executable,String audit,String key){return List.of(executable,"audit","verify",audit,"--audit-key",key);}
    static String readBounded(InputStream input,int maximum) throws IOException {var output=new ByteArrayOutputStream();byte[] buffer=new byte[4096];int total=0,count;boolean truncated=false;while((count=input.read(buffer))>=0){int accepted=Math.min(count,Math.max(0,maximum-total));if(accepted>0){output.write(buffer,0,accepted);total+=accepted;}if(accepted<count)truncated=true;}String value=output.toString(StandardCharsets.UTF_8);return truncated?value+"\n[diagnostic output truncated]":value;}
    static Object[] timelineRow(String[] fields){if(fields.length<=6||!fields[0].equals("CHANGE"))return null;try{return new Object[]{new java.util.Date(Long.parseLong(fields[1])),fields[2],fields[3],fields[4],fields[5],fields[6]};}catch(NumberFormatException error){return null;}}
    static void prependBounded(DefaultTableModel target,Object[] row,int maximum){if(maximum<1)throw new IllegalArgumentException("maximum must be positive");target.insertRow(0,row);while(target.getRowCount()>maximum)target.removeRow(target.getRowCount()-1);}

    private DesktopApp(String executable){
        super("AgentShield — AI Agent Runtime Security");this.executable=executable;setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);setMinimumSize(new Dimension(1180,720));
        var root=new JPanel(new BorderLayout(12,12));root.setBorder(BorderFactory.createEmptyBorder(16,16,16,16));
        var header=new JPanel(new BorderLayout());var title=new JLabel("AgentShield  |  Live observed exposure");title.setFont(title.getFont().deriveFont(Font.BOLD,20f));header.add(title,BorderLayout.WEST);score.setFont(score.getFont().deriveFont(Font.BOLD,16f));header.add(score,BorderLayout.EAST);header.add(identity,BorderLayout.SOUTH);root.add(header,BorderLayout.NORTH);
        var tabs=new JTabbedPane();tabs.addTab("Credentials",tablePane(credentials,"Credential-like environment names visible to the agent"));tabs.addTab("Open resources",tablePane(resources,"Sensitive files and attributed network connections"));tabs.addTab("Risk findings",tablePane(findings,"Explainable security findings and recommended actions"));tabs.addTab("Policy decisions",tablePane(policy,"Allow, approval, and deny decisions"));tabs.addTab("Access timeline",tablePane(activity,"Recent access grants and revocations"));root.add(tabs,BorderLayout.CENTER);
        var controls=new JPanel();controls.setLayout(new BoxLayout(controls,BoxLayout.Y_AXIS));var primary=new JPanel(new FlowLayout(FlowLayout.LEFT));primary.add(new JLabel("Agent PID:"));primary.add(pid);start.setMnemonic('S');primary.add(start);stop.setMnemonic('T');stop.setEnabled(false);primary.add(stop);var policyControls=new JPanel(new FlowLayout(FlowLayout.LEFT));policyControls.add(new JLabel("Audit policy (optional):"));policyControls.add(policyPath);var browse=new JButton("Browse…");policyControls.add(browse);policyControls.add(strictPrivacy);var auditControls=new JPanel(new FlowLayout(FlowLayout.LEFT));auditControls.add(new JLabel("Protected audit log (optional):"));auditControls.add(auditPath);var browseAudit=new JButton("Choose log…");auditControls.add(browseAudit);auditControls.add(new JLabel("Integrity key:"));auditControls.add(auditKeyPath);var browseKey=new JButton("Choose key…");auditControls.add(browseKey);verifyAudit.setMnemonic('V');auditControls.add(verifyAudit);controls.add(primary);controls.add(policyControls);controls.add(auditControls);controls.add(new JLabel("Values are never collected — only credential names and access metadata."));root.add(controls,BorderLayout.SOUTH);
        browse.addActionListener(e->{var chooser=new JFileChooser();if(chooser.showOpenDialog(this)==JFileChooser.APPROVE_OPTION)policyPath.setText(chooser.getSelectedFile().getAbsolutePath());});
        browseAudit.addActionListener(e->{var chooser=new JFileChooser();if(chooser.showSaveDialog(this)==JFileChooser.APPROVE_OPTION)auditPath.setText(chooser.getSelectedFile().getAbsolutePath());});
        browseKey.addActionListener(e->{var chooser=new JFileChooser();if(chooser.showOpenDialog(this)==JFileChooser.APPROVE_OPTION)auditKeyPath.setText(chooser.getSelectedFile().getAbsolutePath());});
        pid.getAccessibleContext().setAccessibleName("Agent process ID");policyPath.getAccessibleContext().setAccessibleName("Optional audit policy file");auditPath.getAccessibleContext().setAccessibleName("Protected audit log file");auditKeyPath.getAccessibleContext().setAccessibleName("Audit integrity key file");strictPrivacy.getAccessibleContext().setAccessibleDescription("Redacts process, credential, resource, endpoint, and cgroup identifiers");
        start.addActionListener(e->begin());stop.addActionListener(e->end());verifyAudit.addActionListener(e->verifyAudit());addWindowListener(new WindowAdapter(){@Override public void windowClosing(WindowEvent event){shutdown();}});setContentPane(root);pack();setLocationRelativeTo(null);
    }
    private JScrollPane tablePane(DefaultTableModel source,String description){var table=new JTable(source);table.setAutoCreateRowSorter(true);table.setFillsViewportHeight(true);table.setRowHeight(24);table.setDefaultRenderer(Object.class,new RiskRenderer());table.getAccessibleContext().setAccessibleDescription(description);return new JScrollPane(table);}
    private static final class RiskRenderer extends javax.swing.table.DefaultTableCellRenderer {@Override public Component getTableCellRendererComponent(JTable table,Object value,boolean selected,boolean focus,int row,int column){var component=super.getTableCellRendererComponent(table,value,selected,focus,row,column);if(!selected){int modelRow=table.convertRowIndexToModel(row);String combined="";for(int i=0;i<table.getModel().getColumnCount();i++)combined+=" "+table.getModel().getValueAt(modelRow,i);if(combined.contains(" CRITICAL")||combined.contains(" BLOCKING")||combined.contains(" DENY")){component.setBackground(new Color(255,225,225));component.setForeground(new Color(140,0,0));}else if(combined.contains(" HIGH")||combined.contains(" ATTENTION")||combined.contains(" APPROVAL")){component.setBackground(new Color(255,244,214));component.setForeground(new Color(105,65,0));}else{component.setBackground(table.getBackground());component.setForeground(table.getForeground());}}return component;}}
    private void begin(){
        String target=pid.getText().trim();if(!target.matches("[1-9][0-9]*")){JOptionPane.showMessageDialog(this,"Enter a valid process ID.");return;}
        String audit=auditPath.getText().trim(),key=auditKeyPath.getText().trim();if(audit.isBlank()!=key.isBlank()){JOptionPane.showMessageDialog(this,"Choose both an audit log and its integrity key, or leave both empty.");return;}
        credentials.setRowCount(0);resources.setRowCount(0);findings.setRowCount(0);policy.setRowCount(0);activity.setRowCount(0);start.setEnabled(false);stop.setEnabled(true);stopRequested=false;
        var command=buildMonitorCommand(executable,target,policyPath.getText().trim(),strictPrivacy.isSelected(),audit,key);
        monitorWorker=new Thread(()->{try{Process process=new ProcessBuilder(command).start();monitor=process;if(stopRequested)process.destroy();var diagnostic=new AtomicReference<>("");var errorReader=new Thread(()->{try{diagnostic.set(readBounded(process.getErrorStream(),65536).trim());}catch(IOException error){diagnostic.set("Unable to read monitor diagnostics: "+error.getMessage());}},"agentshield-diagnostics");errorReader.start();try(var reader=new BufferedReader(new InputStreamReader(process.getInputStream(),StandardCharsets.UTF_8))){String line;while((line=reader.readLine())!=null)handle(line);}int exit=process.waitFor();errorReader.join();String error=diagnostic.get();if(exit!=0&&!error.isBlank())SwingUtilities.invokeLater(()->{score.setText("Monitoring failed");JOptionPane.showMessageDialog(this,error,"Monitor error",JOptionPane.ERROR_MESSAGE);});else SwingUtilities.invokeLater(()->score.setText("Process ended / monitoring stopped"));}catch(IOException ex){SwingUtilities.invokeLater(()->JOptionPane.showMessageDialog(this,ex.getMessage(),"Monitor error",JOptionPane.ERROR_MESSAGE));}catch(InterruptedException ex){Thread.currentThread().interrupt();}finally{monitor=null;monitorWorker=null;SwingUtilities.invokeLater(()->{start.setEnabled(true);stop.setEnabled(false);});}},"agentshield-monitor");monitorWorker.start();
    }
    private void handle(String line){String[] p=line.split("\\t",-1);Object[] resource=resourceRow(p),decision=policyRow(p),change=timelineRow(p);SwingUtilities.invokeLater(()->{if(p.length>8&&p[0].equals("SNAPSHOT")){score.setText("Risk "+p[3]+"/100 — "+p[4]);identity.setText("PID "+p[2]+" | "+p[5]+" | UID "+p[6]+" | capabilities 0x"+p[7]+" | "+p[8]+(p.length>9&&!p[9].isBlank()?" | cgroup "+p[9]:""));credentials.setRowCount(0);resources.setRowCount(0);findings.setRowCount(0);policy.setRowCount(0);}else if(p.length>3&&p[0].equals("CREDENTIAL"))credentials.addRow(new Object[]{p[1],p[2],p[3]});else if(resource!=null)resources.addRow(resource);else if(p.length>5&&p[0].equals("FINDING"))findings.addRow(new Object[]{p[1],p[2],p[3],p[4],p[5]});else if(decision!=null){policy.addRow(decision);if(p[5].equals("BLOCKING"))score.setText("BLOCKED — policy violation detected");}else if(change!=null){prependBounded(activity,change,500);if(p[6].equals("ATTENTION"))score.setText("ATTENTION — new "+p[3].toLowerCase()+" access detected");}});}
    private void verifyAudit(){String audit=auditPath.getText().trim(),key=auditKeyPath.getText().trim();if(audit.isBlank()||key.isBlank()){JOptionPane.showMessageDialog(this,"Choose both the protected audit log and its integrity key.");return;}verifyAudit.setEnabled(false);new Thread(()->{try{Process process=new ProcessBuilder(buildAuditVerifyCommand(executable,audit,key)).redirectErrorStream(true).start();auditVerifier=process;String receipt=readBounded(process.getInputStream(),65536).trim();int exit=process.waitFor();SwingUtilities.invokeLater(()->JOptionPane.showMessageDialog(this,exit==0?"Audit integrity verified.\n\n"+receipt:receipt,exit==0?"Audit verified":"Audit verification failed",exit==0?JOptionPane.INFORMATION_MESSAGE:JOptionPane.ERROR_MESSAGE));}catch(IOException error){SwingUtilities.invokeLater(()->JOptionPane.showMessageDialog(this,error.getMessage(),"Audit verification failed",JOptionPane.ERROR_MESSAGE));}catch(InterruptedException error){Thread.currentThread().interrupt();}finally{auditVerifier=null;SwingUtilities.invokeLater(()->verifyAudit.setEnabled(true));}},"agentshield-audit-verifier").start();}
    private void end(){stopRequested=true;Process process=monitor;if(process!=null)process.destroy();score.setText("Monitoring stopped");}
    private void shutdown(){setEnabled(false);end();Process verifier=auditVerifier;if(verifier!=null)verifier.destroy();new Thread(()->{try{Thread worker=monitorWorker;if(worker!=null)worker.join(3000);Process process=monitor;if(process!=null&&process.isAlive()){process.destroyForcibly();process.waitFor(1,TimeUnit.SECONDS);}}catch(InterruptedException error){Thread.currentThread().interrupt();Process process=monitor;if(process!=null)process.destroyForcibly();}SwingUtilities.invokeLater(()->{dispose();System.exit(0);});},"agentshield-shutdown").start();}
    public static void main(String[] args){String binary=args.length>0?args[0]:"agentshield";try{UIManager.setLookAndFeel(UIManager.getSystemLookAndFeelClassName());}catch(ReflectiveOperationException|UnsupportedLookAndFeelException ignored){ }SwingUtilities.invokeLater(()->new DesktopApp(binary).setVisible(true));}
}
